operations.after:
unary_query: $ => choice(
  // not <media-in-parens>
  prec(1, seq(
    choice('not', 'only'),
    choice($.feature_query, $.range_query, $.parenthesized_query, $.selector_query, $.call_expression, $.general_enclosed),
  )),
  // [not | only] <media-type> [and <media-condition-without-or>]: binds the whole and-chain
  prec(-1, seq(
    choice('not', 'only'),
    $._query,
  )),
),

// Before identifier: an equal-length match prefers the earlier rule
_custom_ident: _ => /--[a-zA-Z0-9-_\xA0-\xFF]*/,

identifier: _ => /(--|-?[a-zA-Z_\xA0-\xFF])[a-zA-Z0-9-_\xA0-\xFF]*/,

// An identifier with escapes (css-syntax-3 4.3.11), e.g. \31 x, x\.y
_escaped_name: $ => choice(
  seq($.escape_sequence, repeat($._name_tail)),
  seq($.identifier, repeat1($._name_tail)),
),

_name_tail: $ => choice(
  alias(token.immediate(/[a-zA-Z0-9-_\xA0-\xFF]+/), $.identifier),
  alias(token.immediate(seq('\\', choice(/[0-9a-fA-F]{1,6}\s?/, /[^0-9a-fA-F\n\r]/))), $.escape_sequence),
),

operations.before:
function sep1(separator, rule) {
  return seq(rule, repeat(seq(separator, rule)));
}

operations.after:
function sep1(separator, rule) {
  return seq(rule, repeat(seq(separator, rule)));
}

/**
 * An at-keyword token matched ASCII case-insensitively, shown as the lower-case literal
 *
 * @param {string} literal
 *
 * @returns {AliasRule}
 */
function kw(literal) {
  const pattern = [...literal].map(c => /[a-z]/.test(c) ? `[${c}${c.toUpperCase()}]` : c).join('');
  return alias(new RegExp(pattern), literal);
}

enum TokenType {
    DESCENDANT_OP,
    PSEUDO_CLASS_SELECTOR_COLON,
    ERROR_RECOVERY,
    CUSTOM_PROPERTY_COLON,
    DOUBLE_QUOTED_CONTENT,
    SINGLE_QUOTED_CONTENT,
    MATH_FUNCTION_NAME,
    URL_FUNCTION_NAME,
};

static const char *const MATH_FUNCTIONS[] = {
    "calc", "-webkit-calc", "-moz-calc", "min", "max", "clamp", "round", "mod", "rem", "sin", "cos", "tan",
    "asin", "acos", "atan", "atan2", "pow", "sqrt", "hypot", "log", "exp", "abs", "sign",
};

static bool is_newline(int32_t c) { return c == '\n' || c == '\r' || c == '\f'; }

// True when a '{' comes before the end of the current statement (';', '}' or EOF).
static bool block_follows(TSLexer *lexer) {
    for (;;) {
        if (lexer->eof(lexer) || lexer->lookahead == ';' || lexer->lookahead == '}') {
            return false;
        }
        if (lexer->lookahead == '{') {
            return true;
        }
        lexer->advance(lexer, false);
    }
}

if (valid_symbols[ERROR_RECOVERY]) {
    return false;
}

// P2-18: string content stops at a newline (bad string), so recovery resynchronises after it
if (valid_symbols[DOUBLE_QUOTED_CONTENT] || valid_symbols[SINGLE_QUOTED_CONTENT]) {
    int32_t quote = valid_symbols[DOUBLE_QUOTED_CONTENT] ? '"' : '\'';
    bool has_content = false;
    while (!lexer->eof(lexer) && lexer->lookahead != quote && lexer->lookahead != '\\' &&
           !is_newline(lexer->lookahead)) {
        advance(lexer);
        has_content = true;
    }
    lexer->result_symbol = quote == '"' ? DOUBLE_QUOTED_CONTENT : SINGLE_QUOTED_CONTENT;
    return has_content;
}

// P2-10: after a custom property name (--*) a colon starts the declaration (css-syntax-3 consume a
// block's contents tries a declaration first, and a qualified rule never starts with "--name:")
if (valid_symbols[CUSTOM_PROPERTY_COLON]) {
    while (iswspace(lexer->lookahead)) {
        skip(lexer);
    }
    if (lexer->lookahead == ':') {
        advance(lexer);
        if (lexer->lookahead != ':') {
            lexer->mark_end(lexer);
            lexer->result_symbol = CUSTOM_PROPERTY_COLON;
            return true;
        }
    }
    return false;
}

// P2-19/P2-20/P2-23: math function and url( names are told apart from other function names
if ((valid_symbols[MATH_FUNCTION_NAME] || valid_symbols[URL_FUNCTION_NAME]) &&
    !(valid_symbols[DESCENDANT_OP] && iswspace(lexer->lookahead))) {
    while (iswspace(lexer->lookahead)) {
        skip(lexer);
    }
    if (iswalpha(lexer->lookahead) || lexer->lookahead == '-') {
        char name[16];
        unsigned length = 0;
        while ((iswalnum(lexer->lookahead) || lexer->lookahead == '-') && lexer->lookahead < 128) {
            if (length < sizeof(name) - 1) {
                name[length] = (char)towlower(lexer->lookahead);
            }
            length++;
            advance(lexer);
        }
        if (lexer->lookahead != '(' || length >= sizeof(name)) {
            return false;
        }
        name[length] = 0;
        lexer->mark_end(lexer);
        if (valid_symbols[URL_FUNCTION_NAME] && strcmp(name, "url") == 0) {
            lexer->result_symbol = URL_FUNCTION_NAME;
            return true;
        }
        if (valid_symbols[MATH_FUNCTION_NAME]) {
            for (unsigned i = 0; i < sizeof(MATH_FUNCTIONS) / sizeof(MATH_FUNCTIONS[0]); i++) {
                if (strcmp(name, MATH_FUNCTIONS[i]) == 0) {
                    lexer->result_symbol = MATH_FUNCTION_NAME;
                    return true;
                }
            }
        }
        return false;
    }
}

operations.before:
if (lexer->lookahead == '#' || lexer->lookahead == '.' || lexer->lookahead == '[' || lexer->lookahead == '-' ||
    lexer->lookahead == '*' || iswalnum(lexer->lookahead)) {
    return true;
}

operations.after:
if (lexer->lookahead == '#' || lexer->lookahead == '.' || lexer->lookahead == '[' || lexer->lookahead == '-' ||
    lexer->lookahead == '*' || iswalnum(lexer->lookahead)) {
    return block_follows(lexer);
}
